mapper.sql:
WHERE t.user_id = #{userId}

    AND t.transaction_date >= CAST(#{dateStart} AS DATE)


    AND t.transaction_date <= CAST(#{dateEnd} AS DATE)


    AND c.name = #{categoryName}


    AND t.amount >= #{amountMin}


    AND t.amount <= #{amountMax}


    AND t.card_name = #{cardName}


    AND t.status = #{status}


    AND t.merchant LIKE '%' || #{search} || '%'
